sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
                // Find any asset_passport record
                var gr = new GlideRecord('x_1919710_refurt_0_asset_passport');
                gr.setLimit(1);
                gr.query();
                if (!gr.next()) {
                    stepResult.setOutputMessage('No asset_passport records found — test skipped');
                    return true;
                }
                var sysId = gr.getUniqueValue();

                var svc = new DPPVerificationService();
                var result = svc.verify(sysId);

                assertEqual({ name: 'Status must be 200', shouldbe: 200, value: result.statusCode });

                var data = result.body;

                // Assert safe fields exist
                var safeFields = ['product', 'model', 'manufacturer', 'passport_status', 'passport_status_label', 'has_confirmed_fraud', 'passport_id'];
                for (var i = 0; i < safeFields.length; i++) {
                    assertEqual({
                        name: 'Field ' + safeFields[i] + ' must exist',
                        shouldbe: true,
                        value: data.hasOwnProperty(safeFields[i])
                    });
                }

                // Assert dangerous fields do NOT exist
                var dangerousFields = ['owned_by', 'risk_score', 'owner', 'cost', 'assigned_to', 'serial_number', 'imei_number', 'managed_by'];
                for (var j = 0; j < dangerousFields.length; j++) {
                    assertEqual({
                        name: 'Field ' + dangerousFields[j] + ' must NOT exist',
                        shouldbe: false,
                        value: data.hasOwnProperty(dangerousFields[j])
                    });
                }

                // Assert total field count is exactly 7
                var fieldCount = Object.keys(data).length;
                assertEqual({ name: 'Exactly 7 fields returned', shouldbe: 7, value: fieldCount });

                stepResult.setOutputMessage('Verified: ' + fieldCount + ' fields returned, all safe');
            })(outputs, steps, params, stepResult, assertEqual);
